import type { Strand } from '../../types';
// Generated by scripts/candidates-to-strands.py from verified RDADA candidates. Dates left null are resolved in threads.ts from the culture spans (and the strand is marked schematic).
type Raw = Omit<Strand, 'start' | 'end'> & { start: number | null; end: number | null; schematic?: boolean };
export const STRANDS_H: Raw[] = [
  { id: 'x-africa-bantu-homeland-bantu-africa-peop', thread: 'th-africa', from: 'bantu-homeland', to: 'bantu-africa', carried: 'people', what: 'Bantu-speaking populations and their genes, with local admixture', medium: 'migration', start: -2500, end: null, directness: 'inferred', status: 'E3', note: 'Genotyping of 1318 individuals from 35 populations in western central Africa, with present-day data, favours the \'late-split\' model: early Bantu speakers moved south through the equatorial rainforest before spreading east and south, admixing with local groups.', for: ["Patin E. (2017): “indicate that BSPs first moved southward through the rainforest before migrating toward eastern and southern Africa”"], against: [], src: ["g_patin2017"], passages: [] },
  { id: 'x-africa-bantu-homeland-bantu-africa-lang', thread: 'th-africa', from: 'bantu-homeland', to: 'bantu-africa', carried: 'language', what: 'Bantu language family', medium: 'migration', start: -3000, end: null, directness: 'inferred', status: 'E3', note: 'A dated phylogeny of about 400 Bantu languages is used to argue that the expansion out of West Central Africa, beginning about 5,000 years ago, followed savannah corridors and that entering rainforest delayed occupation by about 300 years.', for: ["Grollemund R. (2015): “followed emerging savannah corridors, with rainforest habitats repeatedly imposing temporal barriers to movement”"], against: [], src: ["g_grollemund2015"], passages: [] },
  { id: 'x-africa-bantu-homeland-congo-rainforest-lang', thread: 'th-africa', from: 'bantu-homeland', to: 'congo-rainforest', carried: 'language', what: 'Bantu language family, route and timing', medium: 'migration', start: -2470, end: null, directness: 'debated', status: 'E4', note: 'A phylogeographic analysis of the Bantu languages compares four hypotheses and favours an early passage through the rainforest, well before the Sangha River Interval savanna corridor opened (c. 2,500 BP), against the corridor model.', for: [], against: ["Koile E. (2022): “supports the hypothesis of an expansion through Central African tropical forests at 4,420 BP (4,040 to 5,000 95% highest posterior density interval)”"], src: ["g_koile2022"], passages: [] },
  { id: 'x-africa-bantu-homeland-congo-rainforest-peop', thread: 'th-africa', from: 'bantu-homeland', to: 'congo-rainforest', carried: 'people', what: 'early Bantu-speaking settlement of the Congo rainforest (archaeological horizon)', medium: 'migration', start: -1000, end: 0, directness: 'debated', status: 'E4', note: 'A specialist overview says Central African archaeology does not contradict linguistics and genetics on a Bantu migration across the Congo rainforest, with sites suggesting roughly the first millennium BCE, but gaps remain. It lists open questions: farming in the rainforest, deforestation versus clim Also on this strand: Bostoen K.: “much uncertainty persists on the chronology and geography of the Bantu Expansion”', for: [], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["g_bostoennd"], passages: [] },
  { id: 'x-africa-congo-rainforest-bantu-africa-peop', thread: 'th-africa', from: 'congo-rainforest', to: 'bantu-africa', carried: 'people', what: 're-settlement after a population collapse (spread-over-spread)', medium: 'migration', start: 400, end: 600, directness: 'debated', status: 'E4', note: '1149 radiocarbon dates tied to 115 pottery styles from 726 sites show two Iron Age phases split by a population collapse, and the authors conclude with genetic and linguistic evidence that the Bantu dispersal was \'spread-over-spread\', not one continuous wave.', for: [], against: ["Seidensticker D. (2021): “separated by a widespread population collapse between 400 and 600 CE followed by major resettlement centuries later”"], src: ["g_seidensticker2021"], passages: [] },
  { id: 'x-africa-nok-bantu-homeland-tech', thread: 'th-africa', from: 'nok', to: 'bantu-homeland', carried: 'technology', what: 'iron smelting', medium: 'unknown', start: -840, end: -420, directness: 'debated', status: 'E4', note: 'Vansina says the independent-invention question is \'unresolved and hotly disputed\' because the earliest West and West-Central African smelting sites (Taruga and others) cannot be dated more closely than 840-420 BCE on the flat radiocarbon curve; dates before 800 BCE would favour invention, later one Also on this strand: Vansina J. (2006): “cannot be dated more closely than between 840 and 420 BCE”', for: [], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["g_vansina2006"], passages: [] },
  { id: 'x-africa-north-africa-sahara-nok-tech', thread: 'th-africa', from: 'north-africa-sahara', to: 'nok', carried: 'technology', what: 'iron smelting', medium: 'trade', start: null, end: null, directness: 'debated', status: 'E4', note: 'A magazine feature reports a Nok furnace charcoal date of 519-410 BCE at Intini (Breunig) and sets Yale\'s McIntosh, who favours transmission across the Sahara, against those who suspect autonomous West African invention, possibly starting with the Nok. Also on this strand: Atwood R. (2011): “Iron technology was probably brought across the Sahara by travelers from North Africa, says Rod McIntosh” Dates are placed schematically: no source gave them.', for: [], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["g_atwood2011"], passages: [], schematic: true },
  { id: 'x-africa-north-africa-sahara-bantu-africa-tech', thread: 'th-africa', from: 'north-africa-sahara', to: 'bantu-africa', carried: 'technology', what: 'iron smelting', medium: 'unknown', start: null, end: null, directness: 'debated', status: 'E4', note: 'The article summarises the diffusion (Carthage, Meroe) versus independent invention debate, the early Central African Oboui dates (c. 2000 BCE) that Clist calls disturbed while Holl, Craddock and Eggert defend them, and Eggert\'s 2014 view that independent invention is likely though inconclusive. Also on this strand: Wikipedia (pointer): “Opinion among African archaeologists is sharply divided.” Dates are placed schematically: no source gave them.', for: [], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["w_ironmetallurgyinafrica"], passages: [], schematic: true },
  { id: 'x-africa-north-africa-sahara-ghana-mali-reli', thread: 'th-africa', from: 'north-africa-sahara', to: 'ghana-mali', carried: 'religion', what: 'Islam among traders and court officials, beside the king\'s traditional cult', medium: 'trade', start: 1352, end: 1353, directness: 'inferred', status: 'E3', note: 'Describes Ghana as two towns, one Muslim with twelve mosques, one the king\'s, with a mosque for Muslims at court; the king\'s officials are Muslims while the king and his people keep their traditional religion.', for: ["al-Bakri (trans. in Levtzion N. & Hopkins J.F.P.) (1068): “The king's interpreters, the official in charge of his treasury and the majority of his ministers are Muslims.”", "Ibn Battuta (trans. Gibb H.A.R.) (1355): “these people are Muslims, punctilious in observing the hours of prayer, studying books of law, and memorizing the Koran.”"], against: [], src: ["g_albakri1068", "g_ibn1355"], passages: ["p_kitabalmasalik_descriptiono", "p_rihlaadonation_malisectiong"] },
  { id: 'x-africa-arabia-east-africa-coast-peop', thread: 'th-africa', from: 'arabia', to: 'east-africa-coast', carried: 'people', what: 'Arab captains and agents trading and intermarrying on the coast', medium: 'trade', start: 50, end: 70, directness: 'documented', status: 'E2', note: 'The text places Rhapta as the last market-town of Azania, exporting ivory and tortoise-shell, held under the chief of Muza in southern Arabia, whose captains and agents intermarry with the local people and know the language.', for: ["Anonymous (trans. Schoff W.H.) (1912): “using Arab captains and agents, who are familiar with the natives and intermarry with them”"], against: [], src: ["g_anonymous1912"], passages: ["p_periplusmarise_sections1517"] },
  { id: 'x-africa-rome-aksum-reli', thread: 'th-africa', from: 'rome', to: 'aksum', carried: 'religion', what: 'Christianity as the king\'s declared faith', medium: 'court_or_empire', start: 325, end: 360, directness: 'debated', status: 'E4', note: 'Quotes the Christian Greek inscription of Ezana (after Anfray, Caquot and Nautin 1970) as the clearest evidence of his Christianity, with a pseudo-Sabaean and a Ge\'ez version. The author dates the pagan phase to c. 325-333 CE (Munro-Hay) and 333 as a terminus post quem for Christian titulature (Petr Also on this strand: Rukuni R. (2021): “In the faith of God and the Power of the Father, and the Holy Ghost who have saved my kingdom.” Some sources were second-hand.', for: [], against: ["Rukuni R. (2021): “There appears to be debate regarding the dating and actual eventuality of the conversion of Ezana to Christianity.”"], src: ["g_rukuni2021"], passages: ["p_ezanasgreekins_greektextasq"] },
  { id: 'x-americas-balsas-mesoamerica-andes-crop', thread: 'th-americas', from: 'balsas-mesoamerica', to: 'andes', carried: 'crop_or_animal', what: 'maize (Zea mays ssp. mays) domestication and spread', medium: 'unknown', start: -7000, end: -3050, directness: 'inferred', status: 'E3', note: 'Phylogeny of 264 plants genotyped at 99 microsatellites places all maize in one lineage derived from Balsas-drainage teosinte (ssp. parviglumis), against earlier multiple-origin proposals. Also infers spread from the Mexican highlands over the Americas along two paths. Some sources were abstract-only.', for: ["Matsuoka Y. (2002): “all maize arose from a single domestication in southern Mexico about 9,000 years ago”", "Kistler L. (2018): “spread into South America by ~6500 yr B.P.”", "Vallebueno-Estrada M. (2023): “ancient Peruvian maize originated in Mesoamerica as all landraces found to date, followed by a rapid dispersal into the lowlands of South America”"], against: [], src: ["g_matsuoka2002", "g_kistler2018", "g_vallebuenoestrada2023"], passages: [] },
  { id: 'x-americas-n-south-america-west-mexico-tech', thread: 'th-americas', from: 'n-south-america', to: 'west-mexico', carried: 'technology', what: 'copper/bronze metallurgy', medium: 'unknown', start: 700, end: null, directness: 'inferred', status: 'E3', note: 'Hosler\'s own synthesis: West Mexican metalwork first appears c. 700 CE and Mesoamerica is \'an unambiguous case of technology transfer\' from the south, shaped by local preference for sound and colour. Some sources were abstract-only.', for: ["Hosler D. (2014): “metallurgy was introduced from the south, along the Pacific coast, from Northern South America and also from Colombia and Lower Center America”"], against: [], src: ["g_hosler2014"], passages: [] },
  { id: 'x-americas-n-south-america-polynesia-east-peop', thread: 'th-americas', from: 'n-south-america', to: 'polynesia-east', carried: 'people', what: 'Native American admixture', medium: 'unknown', start: 1200, end: 1200, directness: 'debated', status: 'E4', note: 'Abstract (page is a subscription preview): analysis of 807 individuals from 17 island populations and 15 Pacific-coast Native American groups finds Native American admixture in eastern Polynesia from a single contact event, with a group most closely related to present-day Colombia, before the settle Some sources were abstract-only.', for: ["Ioannidis A.G. (2020): “a single contact event occurred in eastern Polynesia, before the settlement of Rapa Nui”"], against: ["Matisoo-Smith L. (2020): “The suggestion that it was Native Americans who made the voyage, however, is where we think this argument goes off the rails.”"], src: ["g_ioannidis2020", "g_matisoosmith2020"], passages: [] },
  { id: 'x-americas-andes-polynesia-east-crop', thread: 'th-americas', from: 'andes', to: 'polynesia-east', carried: 'crop_or_animal', what: 'sweet potato (Ipomoea batatas)', medium: 'unknown', start: 1200, end: 1300, directness: 'debated', status: 'E4', note: 'Commentary on Roullier et al. 2013: the American crop reached Central Polynesia by 1200-1300 CE, most likely carried by Polynesian voyagers who reached South America.', for: ["Denham T. (2013): “Archaeological research has now conclusively shown that the sweet potato was introduced to Central Polynesia by approximately A.D. 1200 to 1300”"], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["g_denham2013"], passages: [] },
  { id: 'x-americas-norse-newfoundland-peop', thread: 'th-americas', from: 'norse', to: 'newfoundland', carried: 'people', what: 'Norse presence in North America', medium: 'migration', start: 1021, end: 1021, directness: 'documented', status: 'E2', note: 'Radiocarbon ring series from Norse-cut wood at L\'Anse aux Meadows, matched to the 993 CE cosmic-ray spike, give a felling year of 1021 CE on three trees.', for: ["Kuitems M. (2022): “Here we provide evidence that the Vikings were present in Newfoundland in AD 1021”"], against: [], src: ["g_kuitems2022"], passages: [] },
  { id: 'x-americas-norse-indigenous-n-america-peop', thread: 'th-americas', from: 'norse', to: 'indigenous-n-america', carried: 'people', what: 'exchange of human genetic information', medium: 'unknown', start: null, end: null, directness: 'debated', status: 'E4', note: 'Same paper, a separate caution: sagas imply cultural exchange with Indigenous people, but Norse Greenlandic genomes show no sign of the exchange of human genetic information. Also on this strand: Kuitems M. (2022): “Recent data from the Norse Greenlandic population, however, show no evidence of the last of these” Some sources were second-hand. Dates are placed schematically: no source gave them.', for: [], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["g_kuitems2022"], passages: [], schematic: true },
  { id: 'x-americas-americas-all-old-world-crop', thread: 'th-americas', from: 'americas-all', to: 'old-world', carried: 'crop_or_animal', what: 'diseases, food crops, technologies', medium: 'conquest', start: 1492, end: null, directness: 'documented', status: 'E3', note: 'Overview of the post-1492 transfer of diseases, food crops and knowledge between hemispheres, stressing effects on the Old World. Also on this strand: Nunn N. (2010): “the exchange of diseases, ideas, food crops, technologies, populations, and cultures between the New World and the Old World after Christopher Columbus\' voyage” Some sources were abstract-only.', for: [], against: [], src: ["g_nunn2010"], passages: [] },
  { id: 'x-east-baekje-yamato-japan-reli', thread: 'th-eastasia', from: 'baekje', to: 'yamato-japan', carried: 'religion', what: 'Buddhist image and sutras sent by King Seong, with a memorial', medium: 'court_or_empire', start: 538, end: 571, directness: 'debated', status: 'E4', note: 'Kimmei 13th year, winter 10th month (Aston prints the year as A.D. 552): King Syeng-myeng of Pekche sends a gold-and-copper Shaka image, flags, umbrellas and sutras, with a memorial praising the doctrine; Soga no Iname is allowed to try the cult, a pestilence follows, and the image is thrown into th', for: ["Aston (1896): “My law shall spread to the East”"], against: ["Yoshida Kazuhiko (2003): “was not translated into Chinese until 703”", "Yoshida Kazuhiko (2015): “should be considered a forgery from a later period”"], src: ["g_aston1896", "g_yoshida2003", "g_yoshida2015"], passages: ["p_nihonshokiniho_bookxixkimme"] },
  { id: 'x-east-goguryeo-yamato-japan-tech', thread: 'th-eastasia', from: 'goguryeo', to: 'yamato-japan', carried: 'technology', what: 'Paper, ink, pigment and millstone making, and Confucian classics, brought by a Buddhist priest', medium: 'court_or_empire', start: 610, end: 610, directness: 'inferred', status: 'E3', note: 'Suiko 18th year (Aston places it in 610): Koguryo sends priests Tam-chhi (Damjing) and Pop-chong; Tam-chhi knew the five Chinese classics, prepared colours, paper and ink, and made mills.', for: ["Aston (1896): “skilled in preparing painters' colours, paper, and ink”"], against: [], src: ["g_aston1896"], passages: ["p_nihonshokiniho_bookxxiisuik"] },
  { id: 'x-east-baekje-yamato-japan-writ', thread: 'th-eastasia', from: 'baekje', to: 'yamato-japan', carried: 'writing', what: 'Chinese writing and tutors, with Wani (Wang-in) as first teacher', medium: 'teaching', start: 285, end: 405, directness: 'debated', status: 'E4', note: 'Aston states that the first positive information on Chinese writing in Japan belongs to A.D. 405, for which the Nihongi gives an erroneous date corresponding to A.D. 285; Wani (Wang-in) of Korea was tutor to an imperial prince, and Korea was the intermediary by which China became known to Japan. Also on this strand: Aston (1896): “The date of its first introduction is not definitely known”', for: [], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["g_aston1896b"], passages: [] },
  { id: 'x-east-china-yamato-japan-writ', thread: 'th-eastasia', from: 'china', to: 'yamato-japan', carried: 'writing', what: 'Chinese characters adapted to record Japanese by phonetic and ideographic use', medium: 'text', start: 711, end: 712, directness: 'documented', status: 'E2', note: 'Yasumaro explains that, ordered in 711 (Wado 4) to record Hieda no Are\'s oral tradition, he wrote with Chinese characters used sometimes by sound and sometimes by sense because archaic Japanese was hard to fit to them; the memorial is dated the 28th day of the 1st month of Wado 5.', for: ["Ō no Yasumaro (1882): “it would be difficult to arrange phrases and compose periods in the characters”"], against: [], src: ["g_kojikipreface1882"], passages: ["p_kojiki_prefaceclosi"] },
  { id: 'x-east-baekje-yamato-japan-idea', thread: 'th-eastasia', from: 'baekje', to: 'yamato-japan', carried: 'idea', what: 'Confucian Analects, Thousand Character Essay and craftsmen via the scholar Wani', medium: 'teaching', start: 285, end: 405, directness: 'debated', status: 'E4', note: 'King Sho-ko of Kudara (Paekche) sends Wani-kishi with the Analects in ten volumes and the Thousand Character Essay in one volume, plus artisans (a smith and a weaver).', for: ["Ō no Yasumaro (1882): “likewise by this man he sent as tribute the Confucian Analects”"], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["g_kojikichamberl1882"], passages: ["p_kojiki_middlevolume"] },
  { id: 'x-east-china-goguryeo-reli', thread: 'th-eastasia', from: 'china', to: 'goguryeo', carried: 'religion', what: 'Buddhist monk, images and scriptures; Confucian academy founded the same year', medium: 'court_or_empire', start: 372, end: 372, directness: 'inferred', status: 'E3', note: 'Sosurim year 2, 6th month (372 by standard reckoning): Fu Jian of Former Qin sends envoys and the monk Sundo (Shun Dao) with Buddha images and scriptures; the king founds a Taehak (academy) to teach youth; year 5 founds Seongmun temple for Sundo and Ibullan for Ado, \'the beginning of Buddhism in Hae', for: ["Kim Busik (compiler): “遣使及浮屠順道，送佛像、經文”"], against: [], src: ["g_kimnd"], passages: ["p_samguksagi_goguryeobong"] },
  { id: 'x-east-goguryeo-silla-reli', thread: 'th-eastasia', from: 'goguryeo', to: 'silla', carried: 'religion', what: 'Buddhism via the monk Mukhoja, officially adopted under Beopheung', medium: 'teaching', start: 417, end: 528, directness: 'inferred', status: 'E3', note: 'Beopheung year 15: Buddhism begins to be practised; the entry recalls the monk Mukhoja coming from Goguryeo to Ilseon commandery in Nulji\'s reign and the court\'s ignorance of incense sent by Liang.', for: ["Kim Busik (compiler): “十五年，肇行佛法”"], against: [], src: ["g_kimndb"], passages: ["p_samguksagi_sillabongi4b"] },
  { id: 'x-east-china-baekje-reli', thread: 'th-eastasia', from: 'china', to: 'baekje', carried: 'religion', what: 'Buddhist monk Maranant\'a and the first Buddhist temple', medium: 'court_or_empire', start: 384, end: 385, directness: 'inferred', status: 'E3', note: 'Chimnyu year 1, 9th month: a foreign (Hu) monk Maranant\'a comes from Jin, is welcomed into the palace and honoured; \'Buddhism began from here\'; a Buddhist temple is founded at Hansan the next year.', for: ["Kim Busik (compiler): “胡僧摩羅難陁自晉至，王迎之，致宮內，禮敬焉。佛法始於此”"], against: [], src: ["g_kimndc"], passages: ["p_samguksagi_baekjebongi2"] },
  { id: 'x-east-china-goryeo-joseon-writ', thread: 'th-eastasia', from: 'china', to: 'goryeo-joseon', carried: 'writing', what: 'Chinese characters judged ill-suited to Korean speech (the preface documents the script\'s unfitness, not its arrival)', medium: 'text', start: 1446, end: 1446, directness: 'inferred', status: 'E3', note: 'Sejong\'s preface says the sounds of Korean differ from China\'s and do not fit Chinese characters, so the common people cannot express themselves; he made 28 letters. The postface is dated 正統十一年九月上澣, the first ten days of the 9th month of Zhengtong 11 (1446).', for: ["Sejong (king) (1446): “國之語音。異乎中國。與文字不相流通”", "Jeong Inji (1446): “假中國文字以通其用”"], against: [], src: ["g_sejong1446"], passages: ["p_hunminjeongeum_prefacesejon", "p_hunminjeongeum_postfaceofje"] },
  { id: 'x-east-china-vietnam-inst', thread: 'th-eastasia', from: 'china', to: 'vietnam', carried: 'institution', what: 'Rites and learning (Xi Guang), field tools and marriage customs (Ren Yan) by Han governors', medium: 'court_or_empire', start: 1, end: 40, directness: 'inferred', status: 'E3', note: 'Xi Guang, grand administrator of Jiaozhi under Emperor Ping, \'taught the people and barbarians, gradually through rites and righteousness\'; Ren Yan in Jiuzhen, where ox-ploughing was unknown, had field tools cast and taught land clearing and set up marriage rules; \'Chinese customs in Lingnan began w', for: ["Fan Ye: “領南華風，始於二守焉”"], against: [], src: ["g_fannd"], passages: ["p_houhanshubooko_ch76xunlilie"] },
  { id: 'x-east-china-vietnam-idea', thread: 'th-eastasia', from: 'china', to: 'vietnam', carried: 'idea', what: 'Confucian learning, classics and rites, credited to governor Shi Xie', medium: 'court_or_empire', start: 187, end: 226, directness: 'debated', status: 'E4', note: 'Ngô Sĩ Liên judges that Vietnam\'s command of the Odes and Documents and of rites, and its status as a land of learning, \'began with the Shi King\' (Shi Xie, governor of Jiaozhi, d. 226 per the entry).', for: ["Ngô Sĩ Liên (1479): “我國通詩書，習禮樂，為文獻之邦，自士王始”"], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["g_ng1479"], passages: ["p_ivitsktonth_ngoikjuan3sh"] },
  { id: 'x-east-china-goguryeo-tech', thread: 'th-eastasia', from: 'china', to: 'goguryeo', carried: 'technology', what: 'Chinese-made paper imported by trade (papermaking itself undated)', medium: 'trade', start: 371, end: 384, directness: 'inferred', status: 'E3', note: 'States that paper made in China was imported to Korea by trade in Sosurim\'s reign, that it is not certain when papermaking was introduced from China, and (separately) that Damjing took papermaking from Goguryeo to Japan in about 610. Also on this strand: Lee J.-Y. (2009): “Paper made in China was imported to Korea by trading during the reign of Sosurim”', for: [], against: [], src: ["g_lee2009"], passages: [] },
  { id: 'x-east-china-goryeo-joseon-tech', thread: 'th-eastasia', from: 'china', to: 'goryeo-joseon', carried: 'technology', what: 'Gunpowder recipe and manufacture', medium: 'trade', start: 1374, end: 1377, directness: 'inferred', status: 'E4', note: 'Choe Museon (1330-1395) learned gunpowder from a Chinese merchant, Li Yuan; a gunpowder office was set up in 1377. Also on this strand: Wikipedia (pointer): “bribed Li for the gunpowder recipe, in violation of Mongol and Chinese law”', for: [], against: [], src: ["w_ch27oemusc58fn"], passages: [] },
  { id: 'x-east-china-latin-europe-tech', thread: 'th-eastasia', from: 'china', to: 'latin-europe', carried: 'technology', what: 'Matchlock gun-lock mechanism, as claimed by Needham', medium: 'unknown', start: 1400, end: 1500, directness: 'debated', status: 'E4', note: 'Notes that Needham argued the Chinese invented the matchlock in the early 1400s and transmitted it westward, and replies that evidence shows it arose in 15th-century southern Germany; follows its spread to China, Korea and Japan.', for: [], against: ["Kang (2022): “But ample evidence shows the contrary”"], src: ["g_kang2022"], passages: [] },
  { id: 'x-east-china-abbasid-tech', thread: 'th-eastasia', from: 'china', to: 'abbasid', carried: 'technology', what: 'The magnetic compass', medium: 'trade', start: 1000, end: 1300, directness: 'debated', status: 'E4', note: 'Summarises the Chinese record of the compass (Han to Song) and states that diffusion is disputed, with transmission via the Arabs or the Indian Ocean proposed and independent European invention also proposed. Also on this strand: Wikipedia (pointer): “Some historians suggest that the Arabs introduced the compass from China to Europe”', for: [], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["w_historyofthecompass"], passages: [] },
  { id: 'x-indianization-india-champa-lang', thread: 'th-seasia', from: 'india', to: 'champa', carried: 'language', what: 'Sanskrit verse edict with Buddhist-sounding ideas of compassion and giving, issued by a descendant of Sri Mara', medium: 'unknown', start: null, end: null, directness: 'inferred', status: 'E3', note: 'Finot\'s catalogue entry gives the damaged Sanskrit stele of Vo Canh (Khanh Hoa), in vasantatilaka metre, with a French rendering of the legible last lines: a king of the line of Sri Mara dedicates his treasure to the welfare of creatures. Finot argues the ideas (impermanence, compassion, giving) are Dates are placed schematically: no source gave them.', for: ["Finot (1915): “L'esprit du grand Açoka revit dans cet édit.”"], against: [], src: ["g_finot1915"], passages: ["p_vocanhinscript_finotcatalog"], schematic: true },
  { id: 'x-indianization-india-champa-peop', thread: 'th-seasia', from: 'india', to: 'champa', carried: 'people', what: 'Indian \'colonisation\' read from the oldest Indochinese Sanskrit inscription', medium: 'unknown', start: null, end: null, directness: 'inferred', status: 'E3', note: 'Finot states that the Vo Canh stele is the oldest inscription of Indochina and pushed the history of Indian colonisation back several centuries, showing how early epigraphy framed the \'colonisation\' model. Dates are placed schematically: no source gave them.', for: ["Finot (1915): “la plus ancienne inscription de l'Indochine, celle de Vó-canh, qui reportait l'histoire de la colonisation indienne à plusieurs siècles en arrière”"], against: [], src: ["g_finot1915"], passages: [], schematic: true },
  { id: 'x-indianization-india-kutai-java-reli', thread: 'th-seasia', from: 'india', to: 'kutai-java', carried: 'religion', what: 'Vedic-style sacrifice and Brahmin priests in royal Sanskrit verse', medium: 'unknown', start: 301, end: 500, directness: 'inferred', status: 'E3', note: 'Vogel\'s transcript and English translation of Yupa A: the king Mulavarman, son of Asvavarman and grandson of \'the great Kundunga\', performed a Bahusuvarnaka sacrifice, the post being prepared by \'the chief amongst the twice-borns\'. Pure Sanskrit verse (anustubh) on a sacrificial post, in Borneo.', for: ["Vogel (1918): “His were three eminent sons resembling the three sacrificial fires.”", "Vogel (1918): “for that deed of merit this sacrificial post has been made by the priests who had come hithers.”"], against: [], src: ["g_vogel1918"], passages: ["p_yupainscriptio_stanzas13lin", "p_yupainscriptio_stanzas45lin"] },
  { id: 'x-indianization-india-kutai-java-writ', thread: 'th-seasia', from: 'india', to: 'kutai-java', carried: 'writing', what: 'Pallava-type (archaic Grantha) script behind the earliest Indonesian and Cham Sanskrit inscriptions', medium: 'unknown', start: 350, end: 450, directness: 'inferred', status: 'E3', note: 'Vogel concludes the Kutai script is most closely related to the archaic Grantha used by early Pallava rulers, and ranks the early records Bhadravarman (Champa), Mulavarman, Purnavarman with c. 50 years between each, so Pallava-derived script is inferred from letter forms, not from a documented route Also on this strand: Vogel (1918): “Professor Kern hesitated between the fourth and fifth century and finally proposed 400 A. D.”', for: ["Vogel (1918): “it is undoubtedly the archaic type of the ancient Grantha character”"], against: [], src: ["g_vogel1918"], passages: [] },
  { id: 'x-indianization-india-funan-peop', thread: 'th-seasia', from: 'india', to: 'funan', carried: 'people', what: 'legendary founder Hundian (=Kaundinya?) and a legend of an overseas hero', medium: 'court_or_empire', start: 0, end: 300, directness: 'debated', status: 'E4', note: 'Fukami translates Kang Tai\'s founding legend (Hundian, a devout man of \'Mofu\', arrives by ship and subdues the queen Liuye) and lists how the Book of Jin, Southern Qi and Liang give the founder\'s origin: \'a foreign country\', \'Jiguo\', \'Jiaoguo ... to the south\'.', for: ["Fukami: “Although the ruler of Funan Liuye tried to seize the ship, Hundian shot an arrow from his sacred bow that pierced her ship”"], against: ["Fukami: “the identification of Hundian’s home country with India is no more than a possibility”", "Fukami: “it demonstrates that there had been little contact between Funan and Tianzhu prior to that time”"], src: ["g_fukamind"], passages: ["p_kangtaiaccount_foundinglege"] },
  { id: 'x-indianization-india-funan-inst', thread: 'th-seasia', from: 'india', to: 'funan', carried: 'institution', what: 'Indian customs and law, brought by a Brahmin Kaundinya (II), c. 400 CE', medium: 'court_or_empire', start: 357, end: 430, directness: 'debated', status: 'E4', note: 'Briggs translates the Liang shu: Kaundinya, \'originally a Brahman of India\', told by a supernatural voice to reign in Funan, is chosen king and reforms its rules by Indian customs. Briggs dates this to about the start of the 5th century, as \'Kaundinya II\'.', for: ["Briggs: “He changed all the rules according to the customs of India.”"], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["g_briggsnd"], passages: [] },
  { id: 'x-indianization-india-funan-reli', thread: 'th-seasia', from: 'india', to: 'funan', carried: 'religion', what: 'resident Indian Brahmans and Brahmanical writings', medium: 'migration', start: 1, end: 514, directness: 'debated', status: 'E4', note: 'Briggs quotes a Chinese report (via Pelliot) that Tun-hsiin, a vassal of Funan on the Malay Peninsula, held more than a thousand Indian Brahmans who married local women, and a Tang report that P\'an-p\'an and Lang-ya-hsiu learn Brahmanical writings and revere the Buddha\'s law.', for: ["Briggs: “They do nothing but read the sacred books of the heavenly spirits [Brahmanical works]”", "Majumdar (1953): “begins with an invocation to Visnu and records the pious donations of Kulaprabhavati, the chief queen of Jayavarman.”"], against: ["Vickery (2003): “There is no evidence of Indianization (religion, art, architecture, state concepts) anywhere in Southeast Asia at that date.”"], src: ["g_briggsnd", "g_majumdar1953", "g_vickery2003"], passages: ["p_neaktadambangd_majumdarno1f"] },
  { id: 'x-indianization-funan-china-idea', thread: 'th-seasia', from: 'funan', to: 'china', carried: 'idea', what: 'foundation legend of Funan as told to the Wu envoys', medium: 'court_or_empire', start: 225, end: 250, directness: 'documented', status: 'E3', note: 'Vickery separates what Kang Tai and Zhu Ying observed at Funan in 245-250 CE from the foundation legend they were told, which he treats as oral tradition, and lists four Chinese versions of it. Also on this strand: Vickery (2003): “These stories are oral traditions, quite different in historical evidential value from the observations made by the envoys”', for: [], against: [], src: ["g_vickery2003"], passages: [] },
  { id: 'x-indianization-india-sea-all-idea', thread: 'th-seasia', from: 'india', to: 'sea-all', carried: 'idea', what: 'Indic materials as raw fragments, \'localized\' by local agents', medium: 'trade', start: 100, end: 1500, directness: 'debated', status: 'E4', note: 'Acri reviews Wolters\'s 1999 \'localization\' model (Southeast Asian adaptation, not Indian imposition), quoting Wolters\'s own definition; Wolters regarded news from India as reaching the region \'fairly promptly and continuously\'. Some sources were second-hand.', for: ["Acri (2017): “Indian materials tended to be fractured and restated and therefore drained of their original significance”"], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["g_acri2017"], passages: [] },
  { id: 'x-indianization-india-sea-all-lang', thread: 'th-seasia', from: 'india', to: 'sea-all', carried: 'language', what: 'Sanskrit cosmopolitan culture adopted by local rulers', medium: 'court_or_empire', start: 300, end: 1300, directness: 'debated', status: 'E4', note: 'Acri reports Pollock\'s counter-argument: Sanskrit use by Southeast Asian rulers shows participation in a cosmopolitan culture driven by local agency, and the \'localization\' evidence is drawn from Sanskrit sources, not independent local ones.', for: [], against: ["Acri (2017): “Pollock has criticized Wolters’ view of an echt “Southeast Asianness” that presupposes an essential and ahistorical cultural substratum”"], src: ["g_acri2017"], passages: [] },
  { id: 'x-indianization-india-sea-all-reli', thread: 'th-seasia', from: 'india', to: 'sea-all', carried: 'religion', what: 'Buddhist knowledge as multidirectional circulation', medium: 'trade', start: 300, end: 1100, directness: 'debated', status: 'E4', note: 'A 2026 integrative review rejects one-way \'Indianization\' in favour of multidirectional circulation and localization of Buddhist knowledge; it also concedes that two of its own cases remain speculative. Also on this strand: Khu (2026): “Such a framework can obscure the historical agency of Southeast Asian societies in selecting, transforming, and circulating cultural and religious knowledge.”', for: [], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["g_khu2026"], passages: [] },
  { id: 'x-indo-pre-anatolian-anatolia-lang', thread: 'th-ie', from: 'pre-anatolian', to: 'anatolia', carried: 'language', what: 'Anatolian branch; earliest records are Hittite names and words in Old Assyrian documents at Kanesh', medium: 'unknown', start: -1900, end: -1800, directness: 'inferred', status: 'E4', note: 'Earliest Anatolian IE attestation is Hittite names and loanwords in Old Assyrian merchant records at Kültepe/Kanesh. The Hittite_language page on Wikipedia says \'as early as the 20th century BC\' (a 19th vs 20th century disagreement between the pages). Also on this strand: Wikipedia (pointer): “The earliest sources of Hittite are the 19th century BC Kültepe texts”', for: [], against: [], src: ["w_anatolianlanguages"], passages: [] },
  { id: 'x-indo-yamnaya-anatolia-lang', thread: 'th-ie', from: 'yamnaya', to: 'anatolia', carried: 'language', what: 'Anatolian branch origin and route', medium: 'migration', start: -2000, end: -1800, directness: 'debated', status: 'E4', note: 'The page presents the Anatolian branch as the earliest split (\'Indo-Hittite\') with a migration into Anatolia in the early 2nd millennium BCE, while the competing farming-from-Anatolia view puts the homeland there; the attestation order does not settle either. Also on this strand: Wikipedia (pointer): “The Anatolian branch is probably the earliest to have split from the Proto-Indo-European language”', for: [], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["w_anatolianlanguages"], passages: [] },
  { id: 'x-indo-germanic-north-alpine-lang', thread: 'th-ie', from: 'germanic-north', to: 'alpine', carried: 'language', what: 'earliest possible Germanic name and Grimm\'s law evidence', medium: 'unknown', start: -350, end: -300, directness: 'debated', status: 'E4', note: 'Negau B bears a North Etruscan-script inscription, read by Markey as Hariχasti teiva \'Harigast the priest\', possibly the earliest Germanic name and earliest Grimm\'s law attestation. Also on this strand: Wikipedia (pointer): “The date of the inscription is unclear, but it may be as old as 350–300 BC”', for: [], against: ["Wikipedia (pointer): “could be a second personal name”"], src: ["w_negauhelmets"], passages: ["p_negauhelmetben_inscriptionh"] },
  { id: 'x-indo-yamnaya-europe-asia-ie-lang', thread: 'th-ie', from: 'yamnaya', to: 'europe-asia-ie', carried: 'language', what: 'origin and timing of Indo-European expansion', medium: 'migration', start: -6000, end: -2000, directness: 'debated', status: 'E4', note: 'Abstract (Crossref record) reports a root age near 8120 BP, not consistent with a purely steppe origin, and proposes a hybrid model. Some sources were abstract-only.', for: [], against: ["Heggarty (2023): “Although this date is not consistent with the Steppe hypothesis, it does not rule out an initial homeland south of the Caucasus”"], src: ["g_heggarty2023b"], passages: [] },
  { id: 'x-islam-byzantium-abbasid-idea', thread: 'th-islam', from: 'byzantium', to: 'abbasid', carried: 'idea', what: 'Greek scientific manuscripts fetched for translation in Baghdad', medium: 'translation', start: 813, end: 833, directness: 'debated', status: 'E4', note: 'Quotes a translation of al-Nadim\'s Fihrist: al-Ma\'mun sends envoys, including Salm, head of the Bayt al-Hikma, to fetch Greek books from Byzantine territory and orders them translated. Also on this strand: Author not stated on the page: “sent forth a group of men among whom were al-Hajjaj, Ibn Matar, Ibn al-Batriq, Salm”', for: [], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["g_authornd"], passages: [] },
  { id: 'x-islam-india-abbasid-idea', thread: 'th-islam', from: 'india', to: 'abbasid', carried: 'idea', what: 'Sanskrit astronomical tables (Sindhind), translated by al-Fazari for al-Mansur', medium: 'translation', start: 772, end: 775, directness: 'documented', status: 'E3', note: 'States that al-Mansur had al-Fazari translate Indian astronomical tables (the Sindhind) after an Indian astronomer\'s visit in 772, and that al-Khwarizmi\'s arithmetic borrows explicitly from India.', for: ["Jaouiche (2010): “In 772, following the visit of a great Indian astronomer to the court of Bagdad, the caliph al-Mansour (754-775)”"], against: [], src: ["g_jaouiche2010"], passages: [] },
  { id: 'x-islam-abbasid-china-inst', thread: 'th-islam', from: 'abbasid', to: 'china', carried: 'institution', what: 'A Muslim merchant community with a judge appointed by the Chinese emperor', medium: 'trade', start: 850, end: 850, directness: 'documented', status: 'E2', note: 'The account says Arab merchants at the Chinese port had a Muslim judge appointed by the Chinese emperor.', for: ["Renaudot (1733): “Soliman the Merchant relates, that at Canfa, which is the principal Scale for Merchants”"], against: [], src: ["g_renaudot1733"], passages: ["p_akhbaralsinwal_solimansacco"] },
  { id: 'x-law-rome-byzantium-inst', thread: 'th-lawchurch', from: 'rome', to: 'byzantium', carried: 'institution', what: 'the structure and much of the text of Gaius\'s elementary Institutes, reused in Justinian\'s Institutes', medium: 'text', start: 161, end: 533, directness: 'inferred', status: 'E3', note: 'Gaius opens his textbook by distinguishing a people\'s own civil law from the law common to all peoples (ius gentium), a frame Justinian\'s Institutes later reuse. Also on this strand: Gaius (English translation as printed on the page: “partly make use of their own laws, and partly have recourse to those which are common to all men”', for: [], against: [], src: ["g_gaiusnd"], passages: ["p_institutesofga_11"] },
  { id: 'x-law-byzantium-bologna-inst', thread: 'th-lawchurch', from: 'byzantium', to: 'bologna', carried: 'institution', what: 'revival of the study of Justinian\'s law books at Bologna (Irnerius)', medium: 'teaching', start: 1084, end: 1125, directness: 'debated', status: 'E4', note: 'Burchard says that Wernerius (Irnerius) renewed the long-neglected books of law at the request of Countess Matilda and, as the next words go, arranged them as Justinian had compiled them; this is a 13th-century report of the Bologna revival, not a contemporary one.', for: ["Burchard of Ursperg (1916): “libros legum, qui dudum neglecti fuerant, nec quisquam in eis studuerat, ad petitionem Mathilde”"], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["g_burchard1916"], passages: ["p_chroniconurspe_mgheditionpa"] },
  { id: 'x-law-early-christianity-rome-reli', thread: 'th-lawchurch', from: 'early-christianity', to: 'rome', carried: 'religion', what: 'Christian communities in the cities, villages and farms of Bithynia, as Pliny reports them', medium: 'unknown', start: 90, end: 112, directness: 'inferred', status: 'E3', note: 'Pliny, as governor of Bithynia-Pontus, reports questioning Christians, executing those who persisted, and what apostates said of their worship. Some sources were second-hand.', for: ["Pliny the Younger: “they were accustomed to meet on a fixed day before dawn and sing responsively a hymn to Christ as to a god”"], against: [], src: ["g_plinynd"], passages: ["p_plinytheyounge_1096"] },
  { id: 'x-law-early-christianity-roman-east-reli', thread: 'th-lawchurch', from: 'early-christianity', to: 'roman-east', carried: 'religion', what: 'commissioned missionary journey of Barnabas and Saul', medium: 'teaching', start: 46, end: 48, directness: 'inferred', status: 'E3', note: 'Antioch\'s church commissions Barnabas and Saul, who sail from Seleucia to Cyprus: the first mission voyage in Acts.', for: ["Luke (traditional attribution: “the Holy Ghost said, Separate me Barnabas and Saul for the work whereunto I have called them”"], against: [], src: ["g_lukend"], passages: ["p_actsoftheapost_1314"] },
  { id: 'x-law-roman-east-rome-reli', thread: 'th-lawchurch', from: 'roman-east', to: 'rome', carried: 'religion', what: 'an existing Christian community at and near Rome', medium: 'unknown', start: 55, end: 60, directness: 'inferred', status: 'E3', note: 'Brethren met at a landing place and then on the Appian Way come out to meet Paul on the road to Rome, indicating a Christian presence there before his arrival.', for: ["Luke (traditional attribution: “they came to meet us as far as Appii Forum, and The three taverns”"], against: [], src: ["g_lukendc"], passages: ["p_actsoftheapost_281416"] },
  { id: 'x-law-rome-early-christianity-inst', thread: 'th-lawchurch', from: 'rome', to: 'early-christianity', carried: 'institution', what: 'toleration and restitution for Christians in the eastern provinces', medium: 'court_or_empire', start: 311, end: 313, directness: 'documented', status: 'E2', note: 'The document, in Lactantius\'s Latin and Eusebius\'s Greek (HE 10.5), grants freedom of religion to Christians and all others and orders return of confiscated property.', for: ["Lactantius (Licinius's letter: “the Christians and all others should have liberty to follow that mode of religion which to each of them appeared best”"], against: [], src: ["g_lactantiusnd"], passages: ["p_lactantiusdemo_48"] },
  { id: 'x-law-church-east-china-reli', thread: 'th-lawchurch', from: 'church-east', to: 'china', carried: 'religion', what: 'Christianity of the Church of the East, brought by Alopen', medium: 'teaching', start: 635, end: 781, directness: 'documented', status: 'E2', note: 'The stele says that the bishop Aluoben (Alopen) from \'Da Qin\' reached Chang\'an in the ninth Zhenguan year (635 CE), was received by the minister Fang Xuanling and had books translated.', for: ["L. Eccles and S. N. C. Lieu (translators) (2023): “from the land of Syria came to Chang’an (Ch’ang-an)”"], against: [], src: ["g_l2023"], passages: ["p_daqinjingjiaol_chinesesecti"] },
  { id: 'x-law-manichaean-roman-north-africa-reli', thread: 'th-lawchurch', from: 'manichaean', to: 'roman-north-africa', carried: 'religion', what: 'Manichaean teaching found among Augustine\'s Carthage circle in the 370s', medium: 'teaching', start: 373, end: 383, directness: 'inferred', status: 'E3', note: 'Augustine describes joining the Manichaeans at Carthage as a young man and the \'Truth, Truth\' language by which they drew him in.', for: ["Augustine of Hippo: “I fell among men proudly raving, very carnal, and voluble”"], against: [], src: ["g_augustinend"], passages: ["p_augustineconfe_3610"] },
  { id: 'x-law-parthian-sasanian-india-reli', thread: 'th-lawchurch', from: 'parthian-sasanian', to: 'india', carried: 'religion', what: 'Mani\'s own mission to India, then Persia, Parthia and Adiabene', medium: 'teaching', start: null, end: null, directness: 'inferred', status: 'E3', note: 'Mani, speaking in the first person, says he preached \'the hope of life\' in India, then returned to Persia, appeared before Shapur and was allowed to preach in Persia, Parthia, Adiabene and to the frontiers of the Roman provinces. Dates are placed schematically: no source gave them.', for: ["Mani (Coptic Kephalaia) (1995): “I crossed from the country of the Indians to the land of the Persians.”"], against: [], src: ["g_mani1995"], passages: ["p_kephalaiaofthe_copticcodexp"], schematic: true },
  { id: 'x-mongol-golden-horde-italian-ports-peop', thread: 'th-plague', from: 'golden-horde', to: 'italian-ports', carried: 'people', what: 'plague (Yersinia pestis) said to be passed to Caffa by catapulted corpses, then to Italy by fleeing Christians; schema has no \'pathogen\' category', medium: 'conquest', start: 1346, end: 1348, directness: 'debated', status: 'E4', note: 'Quotes the Horrox translation of de\' Mussi: dying besiegers had corpses placed in catapults and thrown into Caffa, after which the air and water were tainted. This is the only source for the catapult story. Some sources were second-hand.', for: ["Wheelis M. (2002): “lobbed into the city in the hope that the intolerable stench would kill everyone inside”", "Wheelis M. (2002): “His account of biological attack is plausible, consistent with the technology of the time”", "Bauch M. (2025): “import grain from the Mongols of the Golden Horde around the Sea of Azov in 1347 CE”"], against: ["Zanders J.P. (2021): “regarding events in Caffa, de Mussi was a secondary source, but absent other write-ups, his remains the only contemporaneous account”", "Zanders J.P. (2022): “establishing the plausibility of certain circumstances that might have enabled a certain event to take place still does not prove that the event happened”"], src: ["g_wheelis2002", "g_zanders2021", "g_zanders2022", "g_bauch2025"], passages: ["p_gabrieledemuss_openingnarra"] },
  { id: 'x-mongol-tian-shan-western-eurasia-peop', thread: 'th-plague', from: 'tian-shan', to: 'western-eurasia', carried: 'people', what: 'Y. pestis lineage ancestral to Black Death strains', medium: 'unknown', start: 1338, end: 1346, directness: 'debated', status: 'E4', note: 'Ancient DNA from seven people in two Issyk-Kul cemeteries (tombstones dated 1338-1339 \'pestilence\') gives Y. pestis genomes ancestral to the Black Death diversification, pointing to a Tian Shan source.', for: ["Spyrou M.A. et al. (2022): “our data support an early fourteenth-century source of the second plague pandemic in central Eurasia”"], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["g_spyrou2022"], passages: [] },
  { id: 'x-mongol-golden-horde-latin-europe-peop', thread: 'th-plague', from: 'golden-horde', to: 'latin-europe', carried: 'people', what: 'Y. pestis, single Black Death strain', medium: 'unknown', start: 1340, end: 1353, directness: 'debated', status: 'E4', note: '34 ancient genomes from ten European sites support one entry of plague through eastern Europe and no diversity within the Black Death; the paper says the source and route remain hypothetical. Also on this strand: Namouchi A. et al. (2018): “possibly by means of fur trade routes, as well as the recirculation of plague within the human population”', for: ["Spyrou M.A. et al. (2019): “Our data support an initial entry of the bacterium through eastern Europe, the absence of genetic diversity during the Black Death”"], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["g_spyrou2019", "g_namouchi2018"], passages: [] },
  { id: 'x-mongol-mongol-empire-abbasid-peop', thread: 'th-plague', from: 'mongol-empire', to: 'abbasid', carried: 'people', what: 'plague, described as spreading westward over about fifteen years', medium: 'unknown', start: 1250, end: 1349, directness: 'debated', status: 'E4', note: 'Contemporary Syrian eyewitness places the origin in the \'land of darkness\' (Dols\'s note: \'northern Asia\') and lists spread through China, India, Sind, Uzbek lands, Transoxiana, Persia, Crimea and Rum. Also on this strand: Green M.H. (2024): “reconstruction of the biological processes of ‘focalisation’ is now the most urgent question in plague historiography”', for: ["Dols M.W. (tr.) (1974): “The plague frightened and killed. It began in the land of darkness.”"], against: ["Brack J. (2024): “there is no evidence for the appearance of Plague during or immediately after the Mongol conquests in the Middle East”"], src: ["g_dols1974", "g_brack2024", "g_green2024"], passages: ["p_ibnalwardirisa_dolstranslat"] },
  { id: 'x-mongol-latin-europe-china-tech', thread: 'th-plague', from: 'latin-europe', to: 'china', carried: 'technology', what: 'mangonel/trebuchet building', medium: 'court_or_empire', start: 1268, end: 1273, directness: 'debated', status: 'E4', note: 'Polo says two men of his party, a German and a Nestorian Christian, built stone-throwing engines for Kublai at the siege of Saianfu: a claimed transfer of siege-engine knowledge into Mongol China. Also on this strand: Polo M. (1903): “we have with us among our followers men who are able to construct mangonels which shall cast such great stones”', for: [], against: ["Yule H. (1903): “This chapter is one of the most perplexing in the whole book, owing to the chronological difficulties involved.”"], src: ["g_polo1903"], passages: ["p_marcopoloilmil_bookiichlxxs"] },
  { id: 'x-mongol-latin-europe-mongol-empire-peop', thread: 'th-plague', from: 'latin-europe', to: 'mongol-empire', carried: 'people', what: 'captive craftsmen and clerics', medium: 'court_or_empire', start: 1242, end: 1255, directness: 'documented', status: 'E2', note: 'Rubruck reports a Parisian craftsman, Guillaume Buchier, in the Mongol capital (via Paquette of Metz, a Hungarian captive), a documented trace of Europeans moved across Eurasia by Mongol rule.', for: ["Rubruck W. (1900): “she told us that there was in Caracarum a certain master goldsmith, William by name, a native of Paris”"], against: [], src: ["g_rubruck1900"], passages: ["p_williamofrubru_rockhillpp17"] },
  { id: 'x-mongol-ilkhanate-china-reli', thread: 'th-plague', from: 'ilkhanate', to: 'china', carried: 'religion', what: 'Nestorian and Muslim communities', medium: 'unknown', start: 1253, end: 1255, directness: 'inferred', status: 'E3', note: 'Rubruck describes the Uighur towns as religiously mixed, with Nestorians and Muslims scattered toward Persia and \'all the way to Cathay\'. Also on this strand: Rubruck W. (1900): “in all their towns is found a mixture of Nestorians and Saracens”', for: [], against: [], src: ["g_rubruck1900"], passages: ["p_williamofrubru_rockhillacco"] },
  { id: 'x-mongol-china-ilkhanate-idea', thread: 'th-plague', from: 'china', to: 'ilkhanate', carried: 'idea', what: 'Buddhist and Chinese historical knowledge', medium: 'teaching', start: 1300, end: 1310, directness: 'inferred', status: 'E3', note: 'Rashid al-Din\'s Compendium (composed 1300-10) used a Kashmiri Buddhist monk and Chinese, Uighur and Qipchaq scholars at court as informants. Also on this strand: Melville C. (2021): “political circumstances and Mongol religious tolerance were particularly favorable to the exchange of goods and cultural wares”', for: ["Melville C. (2021): “the Kashmiri monk Kamāl-ashri for the life and teachings of Buddha”"], against: [], src: ["g_melville2021"], passages: [] },
  { id: 'x-mongol-ilkhanate-china-idea', thread: 'th-plague', from: 'ilkhanate', to: 'china', carried: 'idea', what: 'medical and governmental texts', medium: 'translation', start: 1300, end: 1317, directness: 'inferred', status: 'E3', note: 'Popular article saying Rashid had works translated between Arabic, Persian and Chinese; context only. Also on this strand: Lunde P. (1981): “He even had some of his shorter works, on medicine and government, translated into Chinese.”', for: [], against: [], src: ["g_lunde1981"], passages: [] },
  { id: 'x-writing-levant-phoenicia-ugarit-writ', thread: 'th-writing', from: 'levant-phoenicia', to: 'ugarit', carried: 'writing', what: 'alphabetic principle rendered with cuneiform wedges on clay', medium: 'unknown', start: -1400, end: -1190, directness: 'debated', status: 'E4', note: 'Describes the Ugaritic alphabet as a consonantal script written in cuneiform wedges, emerging c. 1400 or 1300 BCE at Ugarit; the article also records the hypotheses that it was inspired by Akkadian cuneiform and/or a Proto-Sinaitic linear alphabet. Also on this strand: Wikipedia (pointer): “written using the same tools as those used to write cuneiform (i.e. pressing a wedge-shaped stylus into a clay tablet”', for: [], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["w_ugariticalphabet"], passages: [] },
  { id: 'x-writing-minoan-cyprus-writ', thread: 'th-writing', from: 'minoan', to: 'cyprus', carried: 'writing', what: 'syllabary used for Greek', medium: 'unknown', start: -1100, end: -300, directness: 'debated', status: 'E4', note: 'The page gives the chain Linear A, Cypro-Minoan, Cypriot syllabary (used c. 11th-4th c. BCE) and says deciphering relied on the Idalion bilingual. Also on this strand: Wikipedia (pointer): “It is thought that the Cypriot syllabary is derived from the Cypro-Minoan syllabary”', for: [], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["w_cypriotsyllabary"], passages: [] },
  { id: 'x-writing-rome-germanic-north-writ', thread: 'th-writing', from: 'rome', to: 'germanic-north', carried: 'writing', what: 'alphabet adapted into the Elder Futhark', medium: 'unknown', start: -100, end: 160, directness: 'debated', status: 'E4', note: 'States the standard view that runes derive from an Old Italic script (Etruscan, Raetic) or Latin, but that no single derivation convinces most scholars and the classical Latin route is awkward for letter shapes; Greek is ruled out by the Vimose date. Also on this strand: Wikipedia (pointer): “there is no derivation so straightforward as to convince most scholars”', for: [], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["w_elderfuthark"], passages: [] },
  { id: 'x-writing-armenia-georgia-writ', thread: 'th-writing', from: 'armenia', to: 'georgia', carried: 'writing', what: 'alphabet', medium: 'teaching', start: 326, end: 450, directness: 'debated', status: 'E4', note: 'Koriwn says Mashtots created a Georgian alphabet and took it to King Bakur and bishop Moses in Georgia. Also on this strand: Wikipedia (pointer): “Another point of contention among scholars is the role played by Armenian clerics in that process.”', for: ["Koriwn (1964): “undertook to create an alphabet for the Georgian language”"], against: ["Specialists disagree about this transfer, and no counter-passage was captured from the sources opened: the other side of the argument is a gap."], src: ["g_koriwn1964", "w_georgianscripts"], passages: ["p_lifeofmashtots_chxvnorehads"] },
  { id: 'x-writing-nabataean-arabia-writ', thread: 'th-writing', from: 'nabataean', to: 'arabia', carried: 'writing', what: 'Arabic written in Nabataean letters', medium: 'unknown', start: 328, end: 328, directness: 'documented', status: 'E2', note: 'English translation after Bellamy of the Arabic epitaph, written in Nabataean letters; the page says it is one of two Arabic inscriptions in a Nabataean alphabet. Also on this strand: Namara inscription (Bellamy translation): “This is the funerary monument of Imru\'l Qais, son of \'Amr, king of of the Arabs”', for: [], against: [], src: ["g_namarainscriptnd"], passages: ["p_namarainscript_lines15"] },
  { id: 'x-writing-china-yamato-japan-writ', thread: 'th-writing', from: 'china', to: 'yamato-japan', carried: 'writing', what: 'phonetic use of kanji, then cursive kana', medium: 'text', start: 800, end: 900, directness: 'inferred', status: 'E4', note: 'States hiragana is simplified cursive kanji by way of man\'yogana (kanji used for sound). Also on this strand: Wikipedia (pointer): “Historically, hiragana developed from cursive forms of kanji via man\'yōgana”', for: [], against: [], src: ["w_hiragana"], passages: [] },
];
